const course: DeepCourse = {"slug":"social-media-manager","title":"Social Media Manager VA.","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Career skill · Pro</p><h1 class=\"display-lg mt-4\">Social Media Manager VA<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Run a brand&#x27;s accounts without quietly becoming its photographer, copywriter, support desk and on-call crisis team for one flat fee.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">5h 24m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Social media managers plan, post and reply for a brand’s accounts — and prove it’s working. This course teaches the systems, plus how to avoid quietly becoming the client’s everything-person for one flat fee.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You already live on these apps and want to get paid for understanding them — without burning out on 24/7 notifications.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A content calendar system, caption and reply frameworks, a reporting template, and boundary scripts for scope creep.</p></div></div></div></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Social media management is the VA job most likely to eat you alive. Not because the work is hard, but because the scope has no natural edge. You start with twelve posts a month and six weeks later you are shooting product photos on a Sunday, answering DMs at midnight, and building a whole brand strategy nobody is paying for.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">So this track teaches two things at once: how to do the work well, and how to draw a line around it. Every module ends with something you can show a client, and half of them end with something you can point at when a client asks for more.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">The running example is Halo-Halo House, a fictional dessert shop in Bacolod with an Instagram, a Facebook page, and a TikTok account nobody has touched since March. You will plan it, write it, design it, schedule it, moderate it, and report on it.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Also posted as</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Social media VA, content coordinator, community manager, digital marketing assistant</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Core loop</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Plan → create → approve → schedule → moderate → report</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Biggest trap</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Scope. One fee, four accounts, unlimited everything</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Four different jobs</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Management, strategy, content production, community management</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Easiest way in</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">A real small business you post for, with permission and a written scope</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Start of shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Inbox and comment sweep</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Comments, DMs, mentions, tagged posts. Reply, escalate, or log. Twenty minutes.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Morning</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Content production block</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Whatever this week&#x27;s calendar says. Design, caption, edit. Batch it, never one post at a time.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Weekly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Calendar and approvals</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Next week&#x27;s posts go to the client with a deadline. No approval by the deadline means it slips, and you say so.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Daily</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Scheduling and QA</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Links, tags, dates, prices, spelling, crop. The five-minute check that saves an apology post.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Ad hoc</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Chasing assets</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">The real bottleneck in this job is never ideas, it is the client not sending the photos.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Monthly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">The report</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Reach, engagement, clicks, saves, and what you would do differently. Three recommendations.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client&#x27;s licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">The stack most PH job posts name</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Canva</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Named in more PH social listings than anything else. Learn brand kits, templates and resize.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Meta Business Suite</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Scheduling, inbox, and insights for Facebook and Instagram in one place. Free.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">CapCut</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Short-form video editing, captions, trending templates. Free and the industry default.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Drive + Sheets</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Asset library and content calendar. Unglamorous and non-negotiable.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Notion or Trello</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Approval workflow. Draft → review → approved → scheduled → published.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Schedulers and extras</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Buffer</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Clean multi-platform scheduling. Generous free tier for one user.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Later</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Visual Instagram planner. Good for grid-conscious brands.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Metricool</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Scheduling plus better analytics than the native apps, including competitor tracking.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Hootsuite</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Older, heavier, still used by agencies. Know it exists.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">TikTok / YouTube Studio</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Native analytics are better than any third-party tool for these two.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Figma</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">When the client has a real brand system and Canva is not enough.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://www.facebook.com/business/learn\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Meta Blueprint</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Free official courses on Facebook and Instagram marketing.</p></a></li><li class=\"h-full\"><a href=\"https://buffer.com/resources/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Buffer Resources</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Honest, data-backed writing about what actually grows accounts.</p></a></li><li class=\"h-full\"><a href=\"https://blog.hootsuite.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Hootsuite blog</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Good for platform updates and benchmark stats to use in reports.</p></a></li><li class=\"h-full\"><a href=\"https://later.com/blog/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Later blog</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Strong on Instagram and TikTok specifics — hooks, hashtags, posting times.</p></a></li><li class=\"h-full\"><a href=\"https://www.canva.com/designschool/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Canva Design School</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Free lessons for the graphics half of this job.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Social media marketing local hourly ranges from OnlineJobs.ph&#x27;s April 2026 guide. These cover execution. Do not confuse them with a US agency&#x27;s monthly strategy retainer, and do not quote one number for management, production, community and strategy bundled together.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Beginner</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">3–6<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:30%;width:30%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Scheduling approved content, basic Canva, comment replies.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 480–960/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Intermediate</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">5–8<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:50%;width:30%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owns the calendar, writes captions, edits video, reports monthly.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 800–1,280/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Expert</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">7–10<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:70%;width:30%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Sets strategy, manages approvals and crises, ties content to outcomes.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,120–1,600/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide, April 2026</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You edit short-form video yourself instead of outsourcing it</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You write captions the client publishes unedited</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You run the approval process instead of waiting inside it</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You can explain why a month underperformed without getting defensive</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You handle community management with a documented escalation path</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You have a scope sheet and you enforce it</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person&#x27;s experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">$1,000 a month, and the scope kept growing</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“It started as two accounts and one or two events. It became four accounts and at least five events a month.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">A widely discussed r/SocialMediaMarketing post described a $1,000/month client: two Instagram accounts and two Facebook accounts, three to four posts a week on one of them, stories, constant comment and DM checking, five or more Facebook events a month, 85% self-created content, copywriting, photography, last-minute changes, and an expectation of being available. The original agreement had been two accounts and one or two events.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The comments did not say &#x27;charge more&#x27;. They said separate the services. As one commenter put it: &quot;social management is different than social strategy which is different than content creation.&quot; Track your actual hours, price each service, and put the extras in writing when they appear, not six months later.</p></div><a href=\"https://old.reddit.com/r/SocialMediaMarketing/comments/1c46eg6/freelance_social_media_pricing/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/SocialMediaMarketing, 2024</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Pick one real account and run it properly for a month</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A friend&#x27;s business, a family shop, a community group. With permission and clear attribution. A month of real posting with real numbers beats any mock portfolio.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Lead with a limited offer</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">&#x27;12 scheduled posts and a monthly report&#x27; is easy to say yes to. &#x27;Full social media management&#x27; makes the client imagine everything they have ever wanted, at your price.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Show the scope sheet during the sales conversation</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Counterintuitive and it works. Serious clients relax when they see boundaries. The ones who bristle at it were going to be the problem client.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Charge separately for production</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Design, video editing and photography are not free extras attached to management. Price them per asset from the first conversation, not after you are already resentful.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Apply for the adjacent titles</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Content coordinator, community manager, digital marketing assistant, social media VA. Same skills, different filter, and often less competition.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Track your actual hours from day one</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Use Toggl. When you find out the ₱15,000 retainer is really 45 hours a month, you have evidence for the renegotiation instead of just a bad feeling.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Brand mini-kit</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows you can work inside a visual system, not just make nice-looking one-offs.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">One-month content calendar</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The single most requested deliverable in social VA interviews.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">One idea across three platforms</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Proves you understand platforms rather than copy-pasting.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Five Canva templates</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Signals you work in batches, which means you are profitable to hire.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Two captioned short videos</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Video editing is the fastest way to move up a rate band right now.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Response bank + escalation matrix</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Almost nobody brings this. It reads as senior immediately.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Monthly analytics report</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows you connect content to outcomes.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Scope sheet with exclusions</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Filters out the clients who would have burned you out.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&#x27;Social media is easy, it&#x27;s just posting&#x27;</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">This client will never accept a rate increase and will question every hour you bill.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>No assets, no approvals, but daily deadlines</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You will be blamed for a bottleneck you do not control. Get the asset deadline in writing first.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Expects replies at any hour</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Community management needs a defined window. Otherwise you are on call for free, permanently.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Photography and video treated as free extras</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">These are the most expensive parts of the work. Price them per asset or exclude them explicitly.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Wants a whole brand strategy for a 12-post fee</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Strategy is a separate project. Bundling it in is how the hourly rate quietly collapses.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Scope grew from 2 accounts to 4 with no fee change</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Renegotiate at the change, not at your breaking point.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Asks you to guarantee viral growth or sales</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You do not control the product, the price, the offer or the funnel. Never promise an outcome you cannot influence.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Wants you to buy followers or run engagement pods</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Fake audiences wreck reach and the client will blame you when the numbers stop working.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Do I need to be good at design?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">You need to be good at using a template. Very different skill. Build five solid Canva templates, respect the brand kit, and you will out-produce someone with better taste and no system.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">What if the client&#x27;s business genuinely has nothing to post about?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Every business has four things: the product, the people who make it, the customers, and how it is made. If none of those produce content, the real problem is that the client will not give you access to any of them. Say that out loud in month one.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How many hours does 12 posts a month actually take?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Batched properly, roughly 8 to 12 hours if you are only designing and scheduling. Add community management and it doubles. Add photography or original video and it doubles again. Track it with Toggl for two months and you will know your real number instead of guessing.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">The client wants me to guarantee growth.<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Guarantee the process, never the outcome. &#x27;I&#x27;ll publish 12 posts, run community management in your window, and report monthly on what moved.&#x27; You do not control the product, the price, or the algorithm.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I run their ads too?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Only if you actually know Ads Manager and you are being paid for it as a separate service. Handling someone&#x27;s ad budget badly is much worse than declining, and &#x27;boost this post&#x27; is not the same skill as running campaigns.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OnlineJobs.ph salary guide</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Social media marketing rates by level. Updated April 2026.</span></a></li><li><a href=\"https://old.reddit.com/r/SocialMediaMarketing/comments/1c46eg6/freelance_social_media_pricing/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/SocialMediaMarketing pricing thread</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The worker story in this course. The comments are the useful part.</span></a></li><li><a href=\"https://www.virtustant.com/roles/social-media-manager\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Virtustant social media manager role</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">A vendor&#x27;s view of the standard stack and a median rate benchmark. Treat it as directional.</span></a></li><li><a href=\"https://ph.indeed.com/q-social-media-manager-canva-l-work-from-home-jobs.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">PH social media job listings (Indeed)</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Read 20 of these before writing your offer. The tool names repeat for a reason.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialization, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/seo-specialist\">SEO Specialist VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/real-estate-va\">Real Estate VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/complete-va-starter\">The Complete VA Starter</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/applications-that-get-replies\">Applications That Get Replies</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/pricing-and-negotiation\">Pricing &amp; Negotiation</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/becoming-an-ops-lead\">Becoming an Operations Lead</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"Four jobs in one job title","outcome":"You can tell a client exactly which of the four social jobs you are doing, and price them separately.","badges":["Time split","Rates","Red/green flags"],"minutes":22,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Social media management is publishing and keeping the accounts alive. Strategy is deciding what the accounts are for. Content production is making the assets. Community management is handling people. They are four different jobs with four different rates.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A post is not a campaign. A campaign has a start, an end, a goal, and a way to tell whether it worked.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every client&#x27;s real goal is one of four: awareness, engagement, leads, or sales. Ask which one, in those words. If they say all four, ask which one they would keep.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Followers are not a business goal. A bakery with 900 local followers who order beats one with 40,000 followers in another country.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write a one-page brief before you touch an account: goal, audience, pillars, platforms, posting cadence, tone, what is off limits.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Getting this straight in week one is the entire difference between a client you keep for two years and one you resent by month three.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The same request, priced four ways</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">MANAGEMENT — Schedule 12 approved posts a month, publish, basic QA. Lowest rate.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">COMMUNITY — Reply to comments and DMs within a defined window, escalate complaints, keep a response log. Priced per week, not per post.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">PRODUCTION — Design 12 graphics and edit 4 reels from client-supplied footage. Priced per asset.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">STRATEGY — Decide the pillars, the calendar, the platform mix, the measurement. Priced as a one-off project, then a monthly retainer.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">When a client asks for &#x27;12 posts a month&#x27;, ask which of these four they mean. Most of them have never thought about it and will respect you for asking.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Where a full social retainer&#x27;s hours actually go</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">20 hrs/week managing two platforms for one small brand. The posting itself is almost nothing.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b1lanpfiuqbtb_\"><title id=\"_R_b1lanpfiuqbtb_\">Making assets: design and video edit 38%, Community: comments, DMs, replies 22%, Planning, ideation, writing captions 16%, Approvals and revisions 10%, Reporting and client comms 8%, Actually scheduling and posting 6%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"133.7061833367816 218.15219386527522\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"77.4088429844525 274.4495342176043\" stroke-dashoffset=\"-133.7061833367816\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"56.297340352329094 295.5610368497277\" stroke-dashoffset=\"-211.1150263212341\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"35.18583772020568 316.6725394818511\" stroke-dashoffset=\"-267.4123666735632\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"28.148670176164547 323.70970702589227\" stroke-dashoffset=\"-302.5982043937689\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"21.111502632123408 330.7468745699334\" stroke-dashoffset=\"-330.7468745699335\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Making assets: design and video edit</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">38%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The real job. Video editing eats hours faster than anything else.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Community: comments, DMs, replies</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">22%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Never batched into one block — it&#x27;s scattered across the day, which is what makes it draining.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Planning, ideation, writing captions</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">16%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Do it monthly in one sitting. Daily ideation is how people burn out.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Approvals and revisions</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">10%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Uncapped revisions is the #1 way this job becomes unprofitable.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Reporting and client comms</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">8%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Small slice, disproportionate effect on whether you keep the client.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Actually scheduling and posting</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">6%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The thing the job is named after takes about an hour a week.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Posting is 6% of the work. If a client is paying you a posting rate for all six slices, you&#x27;re subsidising them by about 90%.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What each of the four social jobs pays</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The reason social media pay looks so random is that four different jobs share one title. Price them separately and you stop being underpaid for the hard one.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Scheduler / poster</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$3–5</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$500–850</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You post what someone else made. Lowest ceiling in the whole VA market.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Community manager</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$5–8</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$850–1,300</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Comments, DMs, tone. Paid for reliability and judgment under pressure.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Content creator (design + video)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$7–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,200–2,200</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You make the assets. Short-form video editing is the highest-demand skill here.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Strategist / social manager</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$10–18</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,700–2,900</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own the calendar, the pillars and the numbers. You can defend a bad month.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Head of social / paid + organic</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$16–28</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,700–4,500</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You tie content to revenue and manage ad spend. Rare and well paid.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><div class=\"mt-4\"><p class=\"eyebrow mb-2 text-muted\">Same skill, different client</p><ul class=\"grid gap-2 sm:grid-cols-2\"><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Verse&#x27;s job board (median)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$4.00</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Across live social listings. Most of those posts want a scheduler and call it a manager.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">US client, direct</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$8–18</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Especially agencies and personal brands. They pay for output volume, not hours.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Per-deliverable (no hourly)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$25–80 per short-form video</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Where experienced editors actually make money. Price the asset, not the afternoon.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Retainer, full social</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$600–2,000/mo</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">12–20 posts + community + reporting. Always cap the revision rounds.</p></li></ul></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sources: Verse&#x27;s live board (n=2,081), OnlineJobs.ph Facebook-marketing expectations ($3.10–12.20+), 2026 agency cards quoting $6–11/hr for social management.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The job post says</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Social Media Manager needed. Post 3x daily on IG, FB, TikTok, X, LinkedIn and Pinterest. Create all graphics and videos. Respond to all comments. Grow us to 100k followers in 6 months. $350/month.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Six platforms × 3 posts = 90 posts a week, plus design, plus video, plus community, for under $2/hr. The follower target is also a promise no honest person can make.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Social manager for our skincare brand. IG + TikTok only, 12 posts/month, we supply raw footage. You edit, caption, schedule and handle comments 2x daily. $900/mo, 20 hrs/wk. Success = engagement rate and DM enquiries, not follower count.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Two platforms, a countable deliverable, they supply the raw material, and success is defined by something the work can actually influence.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A client asks you to guarantee growth</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Sure, we can definitely hit 10k followers in three months with the right strategy!&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Reach is algorithmic and out of your hands. You&#x27;ve just made a promise you&#x27;ll be measured against, and the only way to hit it is buying followers, which wrecks the account.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I can&#x27;t promise follower counts — that&#x27;s the algorithm&#x27;s decision, not mine. What I&#x27;ll commit to is 12 posts a month, every comment answered within 4 hours, and a monthly report on saves, shares and profile-to-DM conversion. Those are the numbers that actually predict sales. If they&#x27;re flat after 90 days, the strategy&#x27;s wrong and I&#x27;ll say so.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Refuses the unpromisable, replaces it with real committed deliverables, and names the metrics that correlate with money instead of ego.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Take Halo-Halo House. Write the one-page brief: goal, audience, three or four pillars, platform mix, cadence, tone, off-limits list.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page brand brief plus a four-line note on which of the four jobs your offer covers.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The goal is one of the four, chosen, not all of them</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The audience is described specifically enough to exclude people</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There are three or four pillars, not seven</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The off-limits list has at least three items</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Your offer note says clearly what you are not doing</span></label></li></ul></div>"},{"n":2,"title":"Content pillars and a calendar that survives","outcome":"You can build a month of content in one sitting instead of panicking daily.","badges":["Workflow","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pillars are recurring subject categories. Three or four, each with a repeatable format. For a dessert shop: the product, the people who make it, the customers, and the behind-the-scenes.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Recurring formats are how you stop starting from zero. &#x27;Flavour Friday&#x27;, a Monday customer photo, a Wednesday behind-the-counter reel. The audience learns the rhythm and so do you.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Batch everything. One planning session, one writing session, one design session, one scheduling session. Doing a full post start to finish every day costs about three times the hours.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build the asset request list at the same time as the calendar, and send it with a hard deadline. Missing photos is the number one reason calendars collapse.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Leave 20% of the calendar empty on purpose. Something will happen, an event, a sold-out day, a trend, and if the month is packed you have nowhere to put it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Seasonal hooks in the Philippines are their own advantage: fiestas, ber-months, payday cycles on the 15th and 30th, back-to-school, rainy season. Local calendars beat generic global ones.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Halo-Halo House, one week from the calendar</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">MON — Pillar: Customers. Format: reposted customer photo + short caption. Asset needed: 2 tagged photos from the weekend.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">TUE — Pillar: Product. Format: single image, price + one-line hook. Asset: ube overload flat lay (client to shoot Sunday).</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">WED — Pillar: Behind the scenes. Format: 20s reel, shaved ice close-up, trending audio. Asset: 3 clips, filmed Tuesday.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">THU — no post. Buffer day.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">FRI — Pillar: Product. Format: carousel, &#x27;how we build a halo-halo&#x27;, 6 slides. Assets: 6 stills.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">SAT — Pillar: People. Format: story sequence, 4 frames, staff pick of the week. Asset: 1 short clip.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">SUN — no post. Buffer day.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">ASSET DEADLINE — everything above due from client by Thursday 5pm the week prior. Late assets push the post, not the deadline.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Five posts, two buffer days, and a deadline the client agreed to in writing. That last line is what stops Sunday-night emergencies.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The monthly batch day</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">One day, once a month. Replaces panicking every morning about what to post.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Pull last month&#x27;s numbers first</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Which 3 posts did best, which 3 died. Do more of the first thing. This takes 15 minutes and shapes everything after it.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Check the calendar for anything real</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Product drops, holidays, local events, client milestones. Real events beat invented content every time.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Fill the pillar grid</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Assign each slot in the month to a pillar. If one pillar is doing all the work, you have one pillar, not four.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write all captions in one sitting</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Writing 12 captions in a row takes about as long as writing 4 on separate days. Context switching is the tax.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Design all assets in one sitting</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Open Canva once. Duplicate a template 12 times. Never build a post from a blank canvas.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Load everything into the scheduler as drafts</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Then send one approval link. One approval round for the month, not twelve.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Leaving 3–4 slots empty for &#x27;timely content&#x27; and then never filling them. Plan 80% and mark the reactive slots explicitly, with a rule for what goes there.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Content pillar sheet</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Build this in week one with the client. It ends the &#x27;what should we post?&#x27; conversation permanently.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[BRAND] CONTENT PILLARS\n\nPillar 1 — TEACH (40% of posts)\nWhat: [the thing your audience doesn&#x27;t know that you do]\nExample formats: how-to carousel, myth vs fact, &quot;3 mistakes&quot; reel\nGoal: saves and shares\nSample: &quot;Why your coffee tastes bitter (it&#x27;s not the beans)&quot;\n\nPillar 2 — PROVE (25%)\nWhat: results, reviews, before/after, customer stories\nExample formats: testimonial graphic, UGC repost, case study reel\nGoal: trust, DM enquiries\nSample: &quot;Marissa switched to weekly delivery — here&#x27;s her setup&quot;\n\nPillar 3 — HUMAN (20%)\nWhat: the people, the process, the mess behind the product\nExample formats: BTS reel, founder talking head, day-in-the-life\nGoal: comments, follows\nSample: &quot;5am at the roastery&quot;\n\nPillar 4 — SELL (15%)\nWhat: the actual offer, plainly\nExample formats: product carousel, offer graphic, launch reel\nGoal: link clicks, sales\nSample: &quot;New: 1kg bags, 20% cheaper per cup&quot;\n\nRULES\n• Never two SELL posts in a row\n• Every SELL post follows at least two value posts\n• If a pillar hasn&#x27;t been posted in 3 weeks, it&#x27;s not a real pillar — cut it\n• Reactive slots: [n] per month, filled only with [trending audio / news in our niche / replies to comments]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Monthly content calendar row</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One row per post in a Sheet or Notion table. Every column earns its place.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Date</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Time</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Platform</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Pillar</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Format</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Hook (first line)</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Caption</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Asset link</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">CTA</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Status</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Posted</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Reach</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Saves</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Comments</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">6pm</td><td class=\"px-3 py-2.5 text-ink-2\">IG Reel</td><td class=\"px-3 py-2.5 text-ink-2\">Teach</td><td class=\"px-3 py-2.5 text-ink-2\">Reel 22s</td><td class=\"px-3 py-2.5 text-ink-2\">&quot;You&#x27;re storing your beans wrong&quot;</td><td class=\"px-3 py-2.5 text-ink-2\">[text]</td><td class=\"px-3 py-2.5 text-ink-2\">[Canva/Drive]</td><td class=\"px-3 py-2.5 text-ink-2\">Save this</td><td class=\"px-3 py-2.5 text-ink-2\">Approved</td><td class=\"px-3 py-2.5 text-ink-2\">✅</td><td class=\"px-3 py-2.5 text-ink-2\">4,210</td><td class=\"px-3 py-2.5 text-ink-2\">189</td><td class=\"px-3 py-2.5 text-ink-2\">23</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 6</td><td class=\"px-3 py-2.5 text-ink-2\">12pm</td><td class=\"px-3 py-2.5 text-ink-2\">IG + FB</td><td class=\"px-3 py-2.5 text-ink-2\">Prove</td><td class=\"px-3 py-2.5 text-ink-2\">Carousel</td><td class=\"px-3 py-2.5 text-ink-2\">&quot;Marissa&#x27;s morning, 6 months in&quot;</td><td class=\"px-3 py-2.5 text-ink-2\">[text]</td><td class=\"px-3 py-2.5 text-ink-2\">[link]</td><td class=\"px-3 py-2.5 text-ink-2\">DM us</td><td class=\"px-3 py-2.5 text-ink-2\">Draft</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">WHY EACH COLUMN\n• Hook gets its own column because it&#x27;s 80% of performance. Review hooks separately from captions.\n• Status: Draft → Review → Approved → Scheduled. Never post anything not marked Approved.\n• The last three columns are filled AFTER posting. This is your evidence at reporting time and your input for next month&#x27;s batch day.</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build a full month for Halo-Halo House. Four pillars, recurring formats, an asset request list with deadlines, and 20% left empty.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A month calendar in Sheets or Notion plus an asset request list the client could action today.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 70 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every entry names its pillar and format</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every entry lists the exact assets needed and who provides them</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a single hard asset deadline stated once, clearly</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least 20% of slots are deliberately empty</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least two entries use a Philippine-specific seasonal hook</span></label></li></ul></div>"},{"n":3,"title":"Writing captions and adapting across platforms","outcome":"You can turn one idea into five platform-native posts without copy-pasting the same caption everywhere.","badges":["Red/green flags","2 templates"],"minutes":32,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The first line is the whole job. On every platform the rest is hidden behind &#x27;more&#x27;, so if line one does not earn attention nothing else you wrote matters.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Three hooks that reliably work: a specific number, a mild contradiction, or a question the audience has actually asked. &#x27;We shave 400 kilos of ice a week&#x27; beats &#x27;Happy Monday everyone!&#x27;.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Platform tone genuinely differs. Instagram is visual-first with a short caption, Facebook tolerates longer and more community-ish, LinkedIn wants a lesson or a result, TikTok wants the hook spoken in the first two seconds.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One clear call to action per post. &#x27;Comment your favourite&#x27;, &#x27;link in bio&#x27;, &#x27;order by Friday&#x27;. Two CTAs is the same as none.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Accessibility is not optional and it also boosts reach: alt text on images, burned-in captions on video, and no walls of decorative emoji between every word, because screen readers read every one out loud.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never make claims the client cannot back. No &#x27;best in Bacolod&#x27;, no health claims, no fake scarcity. You are the one who typed it.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — One idea, five platforms</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Every platform gets: &#x27;Try our new Ube Overload Halo-Halo! 🍧😍 Available now! Visit us today! #halohalo #dessert #bacolod #foodie #yummy #sarap #summer #icecream #philippines #foodporn&#x27;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">IG — &#x27;Nine layers. One of them is a whole slice of leche flan.&#x27; Then two lines on the ube, then: Save this for your next merienda run. (5 hashtags, in the first comment)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">FB — Longer, warmer, community framing: the story of the lola who tested the recipe, plus the address and opening hours because FB is where people actually look those up.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">TIKTOK — Spoken hook at 0:00: &#x27;This is nine layers deep.&#x27; Then the build shot by shot, 22 seconds, captions burned in, price on the last frame.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">IG STORIES — Four frames: teaser, poll (ube vs mango), the build, then a &#x27;we&#x27;re open til 9&#x27; frame with a location sticker.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">LINKEDIN — Skip it. A dessert shop has no reason to be there, and saying so is better advice than filling the slot.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">That last line matters. Telling a client which platform to drop is more valuable than being agreeable and posting into a void.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Adapting one idea across platforms</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Writing one caption and pasting it identically to Instagram, LinkedIn, X and TikTok — hashtags and all.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Each platform rewards a different shape. The LinkedIn crowd finds 30 hashtags spammy, X truncates you, and TikTok wants the hook in the first two words. Copy-paste posting is the clearest signal that nobody is really running the account.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">One idea, four shapes: TikTok gets a 2-word spoken hook and on-screen text; IG gets a carousel with the payoff on slide 2; LinkedIn gets a first-person story with the lesson at the end and no hashtags; X gets the single sharpest sentence with no link in the first post.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Same message, native delivery. This is the difference between &#x27;we&#x27;re on five platforms&#x27; and &#x27;we&#x27;re good on five platforms&#x27;, and it&#x27;s what justifies a manager&#x27;s rate over a scheduler&#x27;s.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Writing the first line of a caption</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;We are so excited to announce that our team has been working hard on something special that we can&#x27;t wait to share with all of you! 🎉✨ Keep reading to find out more...&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Twenty-eight words before any information. The preview cuts off at roughly the first line, so this post&#x27;s entire visible content is &#x27;we are excited&#x27;. Nobody taps &#x27;more&#x27; for that.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;1kg bags. 20% cheaper per cup. Here&#x27;s the maths.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Specific, front-loaded, and creates a small open loop. The reader knows exactly what they&#x27;re getting and has a reason to keep going. Write the first line last, and write five versions of it.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Caption formula (works on every platform)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Five parts. Adjust length per platform, keep the order.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>1. HOOK — one line, under 10 words\n   Make it specific or make it a question they&#x27;d actually ask.\n   Test: would this stop YOUR scroll? If it starts with &quot;We&#x27;re excited&quot;, rewrite it.\n\n2. TENSION — 1–2 lines\n   Why the reader should care. The problem, the mistake, the cost of not knowing.\n\n3. PAYOFF — the substance\n   The actual answer, story or information. Short paragraphs. Line breaks after every 1–2 sentences.\n\n4. CTA — one, never two\n   &quot;Save this for your next grocery run.&quot; / &quot;DM us the word BEANS.&quot; / &quot;Which one&#x27;s you?&quot;\n   A post asking for a follow AND a save AND a comment gets none of them.\n\n5. TAGS — platform-appropriate\n   IG: 3–5 relevant, in the caption. TikTok: 3–4 broad. LinkedIn: 0–3 or none. X: 0–1.\n   Nobody has found 30 hashtags to work since about 2019.\n\nPLATFORM LENGTHS\nTikTok: under 150 chars, hook in the first 2 seconds of the VIDEO not the caption\nInstagram: 125 chars before the cut — everything essential goes before it\nLinkedIn: 210 chars before &quot;see more&quot;. Story format. First person.\nFacebook: 80 chars performs best. Yes, really.\nX: one sentence. Links kill reach — put them in a reply.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">One idea, five posts</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The repurposing worksheet. Fill this in once per idea and you have a week of content.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>CORE IDEA: [one sentence — e.g. &quot;most people store coffee beans in the fridge and it ruins them&quot;]\n\nTIKTOK / IG REEL (20–30s)\nSpoken hook (first 2s): &quot;[3–5 words]&quot;\nOn-screen text: &quot;[different from the spoken hook — read AND heard]&quot;\nBeats: [problem] → [why it happens] → [what to do instead] → [CTA]\nAudio: [trending / original / voiceover]\n\nIG CAROUSEL (5–7 slides)\nSlide 1: the hook, big text, high contrast\nSlide 2: the payoff — don&#x27;t make them swipe 6 times for the answer\nSlides 3–6: detail, one point per slide\nSlide 7: CTA + save prompt\n\nSTATIC GRAPHIC / FB\nOne stat or one sentence. Brand colours. Readable at thumbnail size.\n\nLINKEDIN\nFirst person: &quot;I used to tell customers to refrigerate beans. I was wrong, and here&#x27;s what changed my mind.&quot;\nStory → lesson → soft question at the end.\n\nX / THREADS\nThe single sharpest sentence in the whole idea. No link, no hashtag, no emoji.\n\nSTORIES / REPURPOSE LATER\nPoll: &quot;Fridge or counter?&quot; → reply to results next day → screenshot the best DM reply as its own post</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Take one Halo-Halo House product and write the Instagram caption, the Facebook post, a 20-second TikTok script, and a four-frame story sequence.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page adaptation doc with all four, plus a one-line reason for each platform choice.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every first line works on its own with the rest hidden</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Each version is genuinely different, not the same text reformatted</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">One CTA per post, and they are not all identical</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Alt text written for every image</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No unsupported superlative or health claim anywhere</span></label></li></ul></div>"},{"n":4,"title":"Canva and short-form video, fast","outcome":"You can produce a week of on-brand assets in about ninety minutes.","badges":["Workflow","Tools"],"minutes":38,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a brand kit first: two fonts, five colours with hex codes, logo files, and a photo treatment. Everything after that is fill-in-the-blank.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Five templates carry most brands: single-image announcement, quote or testimonial, carousel cover, carousel inner slide, and reel cover. Build them once, reuse forever.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Text on an image should be readable at thumbnail size. If you cannot read it on your phone from arm&#x27;s length, it is too small, and most people will see it smaller than that.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Video: hook in the first two seconds, subtitles always because most people watch muted, vertical 9:16, and under 30 seconds until you have a reason to go longer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Only use music from the platform&#x27;s own library or a properly licensed source. A copyright strike on a client&#x27;s account is a genuinely serious mistake and it is hard to undo.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never use photos you found on Google. Client-supplied, properly licensed stock, or you shot it. Stolen product photos are a real legal problem, not a technicality.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep a clean file naming system: brand_pillar_date_version. Six months in, you will need to find something, and &#x27;Untitled design (14)&#x27; will not help.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The 90-minute batch</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">0:00–0:10 — Pull the week&#x27;s assets from Drive into one folder. If something is missing, message the client now, not at minute 80.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">0:10–0:35 — Fill five Canva templates with this week&#x27;s copy. No new designs, only templates.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">0:35–1:05 — Cut two reels in CapCut from the same footage. Auto-captions, then fix the words it got wrong, especially Filipino words.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1:05–1:20 — Write all captions in one doc, all at once. Voice stays consistent when you write them together.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1:20–1:30 — QA pass and load into the scheduler as drafts for approval.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">A week of content in ninety minutes is how a social VA makes a decent hourly rate on a fixed monthly fee. Doing it post-by-post is how you make ₱90 an hour.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">A week of assets in ninety minutes</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">After batch day, once the captions are approved.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Build the template set ONCE</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Five templates: carousel cover, carousel inner, quote card, stat card, reel cover. Locked brand colours and fonts. You never make these again.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Duplicate, don&#x27;t create</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every post starts as a copy of a template. If you&#x27;re choosing a font, you&#x27;re already losing. The consistency is a feature, not laziness.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Batch all text first, all images second</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Fill every template with copy in one pass, then do one image pass. Switching between writing and visual work is what makes this slow.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Video: cut to the beat, caption everything</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Auto-caption in CapCut, then read them — auto-captions mangle brand and Filipino words constantly. 85% of people watch on mute.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Check at thumbnail size</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Shrink every asset to 20%. If the hook isn&#x27;t readable, the text is too small. This one check fixes most amateur-looking design.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Export with a naming convention</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">[date]-[platform]-[pillar]-[v1].png. Future you, hunting for an asset a client wants reused, will be grateful.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Perfecting one post for 45 minutes. Social content has a 48-hour lifespan. Done and posted beats perfect and late, every single time.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Design and video tools</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Learn one design tool and one video tool properly. Six half-known tools is worth less than two you&#x27;re fast in, and speed is literally what you&#x27;re selling.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Canva</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Everything static, plus quick video. Brand kits and client sharing.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a weekend to get fast</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier, $10/mo Pro</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Non-negotiable. Learn Brand Kit, Magic Resize and templates — not the fancy effects. Speed comes from never starting blank.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">CapCut</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Short-form vertical video, auto-captions, trending templates.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a weekend</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free (Pro $8/mo)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The default for TikTok/Reels editing worldwide. Auto-captions alone will save you hours a week. Learn this second.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Figma</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Precise design work and anything a developer will use.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — a week</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier is generous</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Overkill for most social work, but knowing it lets you take higher-paying design-adjacent jobs. Learn after the first two.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Adobe Express</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Clients already locked into Adobe.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier, $10/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Only if a client insists. Canva does the same job with better templates and a bigger community.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Descript</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Editing talking-head video by editing the transcript text.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — genuinely fun</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier, $19/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Underrated. If a client does podcasts or long-form video, this turns a 2-hour edit into 20 minutes. Strong differentiator.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Premiere / After Effects</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">High-end video with real motion graphics.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Hard — months</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$23–60/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Don&#x27;t. Not for social VA work. CapCut plus good taste beats bad Premiere every time, and it&#x27;s ten times faster.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build the Halo-Halo House brand kit and five templates, then produce one carousel and one 20-second captioned video.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A Canva brand kit link, five templates, one 6-slide carousel, one captioned vertical video.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 90 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Brand kit has two fonts and five hex codes written down</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">All five templates use only those fonts and colours</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Video has burned-in captions and is 9:16</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every file follows one naming convention</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You can state where every image and every audio track came from</span></label></li></ul></div>"},{"n":5,"title":"Approvals, scheduling, and the QA check","outcome":"You can run an approval workflow that protects you when something goes wrong.","badges":["Workflow","2 templates"],"minutes":24,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Five states, no ambiguity: draft, in review, approved, scheduled, published. If a client asks &#x27;did that go out&#x27;, the board should answer without you looking.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One approver. Not &#x27;the team&#x27;. When three people give notes you get contradictions and you are the one who absorbs the delay.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Set a revision limit in the scope, usually two rounds. Round three onward is billable. This is normal in every creative industry and clients accept it when it is written down in advance.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Approval deadline: assets and sign-off by a fixed day, or the post slips a week. Say it once, kindly, then actually do it. The first time you enforce it is the last time it is a problem.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The pre-publish QA check, every time: link works, tags correct, date and time right, price correct, spelling, crop on all sizes, and does the caption match the image.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Know what boosted means before a client asks. A boost is paid distribution of an existing post and it comes out of an ad budget, not your fee. Paid ads management is a separate service.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The seven-point QA check, applied</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Post goes live: &#x27;Ube Overload, ₱180, available til Sunday!&#x27; with a link to the old menu PDF and the photo cropped so the flan is cut off.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">LINK — opens, goes to the current menu, not a 404 or a stale PDF (pass)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">TAGS — @halohalohouse tagged, location sticker set to the Bacolod branch (pass)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">TIMING — scheduled 11:30am, before the lunch decision, not 9pm (pass)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">PRICE — confirmed ₱195 with the client on 2 Aug, caption corrected (pass)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">SPELLING — read out loud once (pass)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">CROP — checked in feed, grid and story sizes. Flan visible in all three (pass)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">MATCH — caption says nine layers, image shows nine layers (pass)</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Five minutes. It prevents the apology post, the deleted post, and the awkward message where a client asks why the price was wrong.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Approval flow that protects you</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every post, without exception, including the ones the client &#x27;already saw&#x27;.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Batch the month into one approval link</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not 12 separate messages. A single view where they can comment per post.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Set a deadline with a stated default</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;Please review by Thursday. Anything unmarked on Friday morning, I&#x27;ll treat as approved and schedule.&quot; Without a default, you wait forever.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Cap revisions in writing</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Two rounds included. Round three is billed. Say this at contract time, not the first time it happens.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Get approval in a place with a timestamp</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Comment, email, or a checkbox in the sheet. Never a verbal yes on a call. When something goes wrong, the timestamp is your whole defence.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Run the QA check before scheduling</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The pre-flight list. Every post, every time, even the boring ones.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Screenshot the scheduled queue</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Proof the work was done and queued, in case a platform silently fails to publish. It happens more than you&#x27;d think.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>&quot;They said it was fine on the call.&quot; If it isn&#x27;t written down, it didn&#x27;t happen, and you&#x27;ll be the one who posted the wrong price.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Pre-flight QA checklist</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Run before anything goes into the scheduler. Every item on this list exists because someone got burned by it.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>POST: [date] [platform]\n\nFACTS\n[ ] Every price, date, discount and deadline checked against the source\n[ ] Product name spelled exactly as the brand spells it\n[ ] Any @mention is the RIGHT account (check the profile, not the handle)\n[ ] Link works, goes to the right page, and isn&#x27;t a staging URL\n[ ] Nothing claimed that the client can&#x27;t back up (health, income, &quot;best&quot;, &quot;#1&quot;)\n\nCRAFT\n[ ] Hook visible before the &quot;more&quot; cut\n[ ] Spelling and grammar — read it out loud\n[ ] Captions on video, and CHECKED (auto-captions mangle names constantly)\n[ ] Readable at thumbnail size\n[ ] Correct aspect ratio: 9:16 vertical, 4:5 feed, 1:1 grid\n[ ] Alt text written — accessibility, and it helps discovery\n\nRIGHTS + SAFETY\n[ ] Music is licensed or from the platform&#x27;s own library (commercial accounts get muted for trending audio)\n[ ] Every person in frame has consented, especially customers and children\n[ ] UGC has explicit permission, screenshotted, and credit in the caption\n[ ] No customer faces, order numbers, addresses or DMs visible in screenshots\n\nCONTEXT — the one everyone skips\n[ ] Check the news. Do not post a jokey reel during a typhoon, a disaster or a national tragedy.\n[ ] Nothing scheduled for a date that has since become sensitive\n[ ] Anything auto-scheduled during a live crisis gets PAUSED\n\nAPPROVAL\n[ ] Written approval exists, with a timestamp\n[ ] Scheduled for the right timezone (check twice — this is the classic error)</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Approval request message</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Send with every batch. The deadline and the default are the two load-bearing sentences.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Hi [name] — [month]&#x27;s content is ready to review.\n\n[Link to the calendar/board]\n\n[n] posts across [platforms]. Each one has the caption, the asset and the scheduled date.\n\nHow to review:\n• Approve: tick the Status column, or just reply &quot;all good&quot;\n• Change something: comment on that specific post — please be specific, &quot;make it pop&quot; gives me nothing to work with\n• Two rounds of revisions are included, as per our agreement\n\nDeadline: [day]. Anything not commented on by [day] morning I&#x27;ll take as approved and schedule, so we don&#x27;t lose the posting slots.\n\nOne thing I need from you: [the photo / the price confirmation / the founder quote].</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Set up an approval board in Trello or Notion with the five states, then run your module 4 assets through it and QA every one.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A screenshot of the board plus a completed seven-point QA sheet for four posts.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Board has exactly five states and every card sits in one</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">One named approver and one approval deadline are written on the board</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The revision limit is stated somewhere visible</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every QA row is ticked individually, not in bulk</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You caught at least one real error</span></label></li></ul></div>"},{"n":6,"title":"Community management and the bad day","outcome":"You can handle comments and DMs at speed, and you know exactly when to stop typing and escalate.","badges":["Workflow","Red/green flags","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Sort every incoming message into five types: question, compliment, complaint, spam, and crisis. Each has a different route and only one of them goes to the client immediately.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a response bank of 15 to 20 approved replies for the routine stuff. Adapt each one slightly so it does not read like a bot, but never start from a blank box at 2am.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never argue in public. Acknowledge, apologise if warranted, move it to DM, resolve it there. One line, then take it private.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Escalate immediately for anything involving illness, injury, allergies, legal threats, accusations of discrimination, staff conduct, or a journalist. You do not reply to those, ever, no matter how obviously wrong the person is.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Speed matters more than polish for complaints. A fast &#x27;we&#x27;ve seen this and we&#x27;re on it&#x27; beats a perfect reply four hours later.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Log everything. Date, platform, type, what you did. When a client asks why a customer was angry in March, the log is the reason you still have the account.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Agree a response window in the scope. &#x27;Weekdays 9am to 6pm PH, next business day on weekends&#x27; is a real service. &#x27;Always&#x27; is not a service, it is an unpaid on-call rota.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Crisis drill: &#x27;I got sick after eating here&#x27;</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&#x27;That&#x27;s impossible po, our kitchen is very clean and we&#x27;ve never had a complaint. Are you sure it was us? 😊&#x27;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">PUBLIC (within 15 minutes): &#x27;I&#x27;m really sorry to hear this. Sending you a DM now so we can get the details and look into it properly.&#x27;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">DM: ask date, time, order, symptoms. No apology that admits fault, no denial, no arguing. Just collect facts.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">ESCALATE: message the owner immediately with a screenshot. This is a health complaint and the VA does not handle it.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">LOG: date, platform, handle, what was said, what you sent, who you escalated to, at what time.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">DO NOT: delete the comment, hide the comment, or reply again until the owner says what to say.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Deleting it is the instinct and it is the worst option. Screenshots outlive deleted comments, and &#x27;they deleted my comment&#x27; becomes the actual story.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Comment and DM triage</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Twice a day, timeboxed. Not continuously — that way lies madness.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Sort into five buckets before replying to anything</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Buying signal / genuine question / praise / complaint / abuse-and-spam. Speed of sorting beats speed of replying.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Buying signals first, always</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;How much?&quot;, &quot;do you deliver to...?&quot;, &quot;is this available?&quot; These are money. Reply within the hour and route to whoever closes.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Answer questions with the answer, not a deflection</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;DM us for pricing&quot; makes people leave. Post the price. The people who won&#x27;t DM are the majority.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Acknowledge praise briefly and specifically</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not a heart emoji on all forty. Two sentences on the good ones — those people become repeat customers and UGC.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Complaints: acknowledge, take it private, follow up in public</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Never argue in a thread. &quot;That&#x27;s not the experience we want you to have — DM&#x27;d you.&quot; Then actually fix it and reply once more publicly when it&#x27;s resolved.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Hide, don&#x27;t delete; block, don&#x27;t engage</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Hiding is invisible to the poster and defuses things. Deleting gets screenshotted. Never reply to abuse — ever.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Replying to a complaint while annoyed. Write it, don&#x27;t send it, wait ten minutes. The internet keeps screenshots forever and the client&#x27;s brand is not yours to risk.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A public complaint on a post</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;That&#x27;s actually not true, our shipping policy is clearly stated on the website. You agreed to the terms at checkout. 🙄&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Correct and catastrophic. You&#x27;ve won an argument with a customer in front of every future customer. The eye-roll emoji alone could end the client relationship.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Hi Anna — three weeks is way longer than it should be and I&#x27;m sorry. I&#x27;ve sent you a DM to get your order number so we can sort it today.&quot;\n\n[Then, once resolved:]\n&quot;Update for anyone following — Anna&#x27;s order landed this morning and we&#x27;ve fixed the courier issue that caused it.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Named her, acknowledged the actual problem, moved it private, and closed the loop publicly. Onlookers now think the brand handles problems well, which is worth more than being right.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You genuinely don&#x27;t know the answer to a customer&#x27;s question</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Guessing. &quot;I think it&#x27;s about 3–5 days?&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">A wrong answer in writing from the brand account is worse than no answer. You&#x27;ve just created a promise the business has to keep or apologise for.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Good question — I want to give you the right answer rather than a guess. Checking with the team and I&#x27;ll come back to you today.&quot; Then set a reminder and actually come back.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Buys time without losing trust. The follow-through is the part that matters, so put it in your tracker immediately.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Escalation rules — agree these in week one</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The single most important document in community management. It&#x27;s what stops a bad day becoming a fired-VA day.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[BRAND] — WHEN I STOP TYPING AND CALL YOU\n\nI HANDLE ALONE (no need to ask)\n• Pricing, stock, hours, delivery areas, how the product works\n• Praise and general chat\n• Repeat FAQs — using the saved replies below\n• Obvious spam and bots (hide + block, no reply)\n\nI DRAFT, YOU APPROVE (within [n] hrs)\n• Any complaint about a specific order\n• Anything where we&#x27;d offer a refund or a freebie\n• Collaboration and partnership enquiries\n• Press or media questions\n• Anything a competitor is mentioned in\n\nI STOP AND CALL YOU IMMEDIATELY — no reply at all until we&#x27;ve spoken\n• Legal threats or the word &quot;lawyer&quot;\n• Allegations about safety, health, or someone getting hurt\n• Racism, harassment, or abuse toward staff\n• Anything that&#x27;s being shared/quoted fast (a pile-on)\n• Accusations of scamming or fraud\n• Anything involving a minor\n• A hacked or impersonated account\n\nCONTACT DURING A CRISIS\n1. [Name] — [phone] — call, don&#x27;t message\n2. If no answer in 30 min: [Name] — [phone]\n3. If neither: I pause all scheduled posts and reply to nothing. Silence is safer than a wrong answer.\n\nMY HOURS\nComments checked [time] and [time], Mon–Fri.\nOutside those hours nobody is watching. If you need 24/7 cover, that&#x27;s a different scope and a different price.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Saved replies library</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Build 10–15 of these in week one. Community management gets 5× faster and stays on-brand.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>PRICE ASK\n&quot;Hi [name]! [Product] is ₱[price] for [size]. Delivery within [area] is ₱[x], free over ₱[y]. Want me to send the link?&quot;\n\nDO YOU DELIVER TO ___\n&quot;We deliver to [areas] — [area] included! [n] days, ₱[x]. Anywhere else it&#x27;s [courier], [n] days. Where are you based?&quot;\n\nIS IT AVAILABLE\n&quot;Yes, in stock right now 🙌 [link]. Only [n] left of [variant] though, just so you know.&quot;\n\nCAN I GET A DISCOUNT\n&quot;We don&#x27;t do individual discounts, but [the honest alternative — bundle, first-order code, newsletter offer]. That&#x27;s the best price we do.&quot;\n\nCOLLAB REQUEST\n&quot;Thanks for thinking of us! We look at collabs monthly — send your rates and recent work to [email] and the team will come back to you.&quot;\n\nWHERE&#x27;S MY ORDER\n&quot;Sorry for the wait! Can you DM me your order number and I&#x27;ll chase it right now?&quot;\n[Then escalate per the rules above.]\n\nCOMPLAINT — FIRST PUBLIC REPLY\n&quot;Hi [name] — that&#x27;s not how this should have gone and I&#x27;m sorry. I&#x27;ve DM&#x27;d you so we can sort it out properly.&quot;\n\nTONE RULES\n• Use their name\n• Never more than 2 emojis, never a 🙄 or a 😂 at a customer\n• No corporate voice — write like a person who works there\n• Never say &quot;unfortunately&quot; — say what you CAN do instead</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write a 15-reply response bank for Halo-Halo House, then an escalation matrix, then run yourself through three crisis scenarios you invent.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A response bank, an escalation matrix, and three written crisis responses with escalation steps.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 55 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every reply in the bank sounds like a person, not a template</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The matrix names who to escalate to and how fast for each type</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">None of your crisis responses admit fault or deny fault</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every crisis response moves the conversation to DM in one line</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You wrote down the response window you would put in the contract</span></label></li></ul></div>"},{"n":7,"title":"Analytics without vanity metrics","outcome":"You can report on what a business actually cares about and defend a month where the numbers dipped.","badges":["Time split","Red/green flags","1 template"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Reach is unique accounts that saw it. Impressions is total views including repeats. Mixing them up in a client report is an instant credibility loss.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Saves and shares are the strongest signals on Instagram. A post with 40 likes and 30 saves is doing far more work than one with 300 likes and 2 saves.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Compare to the previous period and to the same period last year. One month in isolation tells you almost nothing, especially for a seasonal business.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Follower growth is not a business outcome. If the client wants sales, report link clicks, profile visits, DM enquiries, and anything you can trace to an order.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Report the losses too. &#x27;Reels underperformed this month, I think because we posted three of them at 9pm on weekdays. Testing 11:30am next month.&#x27; That sentence buys you more trust than any green arrow.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Exactly three recommendations. More than three and nobody does any of them.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Two versions of the same month</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&#x27;Great month! Reach 12,400 (up!), 87 new followers, engagement is strong. Keep it up! 🎉&#x27;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">REACH — 12,400, up 18% vs July, but 61% of it came from one reel. Take that out and the baseline is flat.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">SAVES — 214, up from 96. The carousels are doing the work; the single-image posts are not.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">PROFILE → LINK — 340 profile visits, 41 link clicks (12%). Last month 9%.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">ENQUIRIES — 23 DM enquiries about catering, up from 8. This is the number that matters for the goal we set.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">DIDN&#x27;T WORK — Weekday 9pm posts. Consistently the lowest reach. Stopping those.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">NEXT — 1) Two carousels a week instead of one. 2) Move all posting to 11:00–12:00. 3) Add a catering highlight to the profile, since that is where enquiries are coming from.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second one reads like someone running a business, not someone hoping not to get fired. It also makes a rate increase much easier to ask for later.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Which metrics actually predict a sale</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Rough weighting of how much attention to give each metric when you report. Not a data split — a priority split.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b7lanpfiuqbtb_\"><title id=\"_R_b7lanpfiuqbtb_\">DMs and enquiries generated 30%, Saves and shares 25%, Profile visits and link clicks 20%, Comments (real ones, not emoji) 12%, Reach and impressions 8%, Follower count and likes 5%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"105.55751316061705 246.30086404143978\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"87.96459430051421 263.89378290154264\" stroke-dashoffset=\"-105.55751316061705\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"70.37167544041137 281.48670176164546\" stroke-dashoffset=\"-193.52210746113127\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"42.223005264246815 309.63537193781\" stroke-dashoffset=\"-263.89378290154264\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"28.148670176164547 323.70970702589227\" stroke-dashoffset=\"-306.11678816578944\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"17.59291886010284 334.265458341954\" stroke-dashoffset=\"-334.265458341954\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">DMs and enquiries generated</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">30%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The closest thing to revenue you can see from inside the app.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Saves and shares</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">25%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Intent signals. Someone saving a post is planning something.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Profile visits and link clicks</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">20%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">They left the feed to look you up. That&#x27;s real interest.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Comments (real ones, not emoji)</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">12%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Questions in comments are buying signals hiding in plain sight.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Reach and impressions</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">8%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Context only. Useful to explain a spike, useless as a goal.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Follower count and likes</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">5%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Report it because clients ask. Never optimise for it.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">If you can teach a client to care about saves and DMs instead of followers, you&#x27;ve changed how they judge you — from something you can&#x27;t control to something you can.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The metric you lead the report with</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;We gained 1,200 followers this month! 🎉 Our reach was 84,000 and we got 3,400 likes.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">All three are vanity metrics. Followers can be bought or come from a fluke viral post of the wrong audience. Reach counts people who scrolled past. None of it tells the owner whether they made money.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Profile visits → DM enquiries: 47 this month, up from 31. Saves per post averaged 89, which is the strongest predictor we have of someone buying later. Followers went up 1,200 but honestly most came from one reel that reached the wrong audience — I&#x27;d ignore that number.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Leads with the metric closest to money, explains why saves matter, and openly discounts the flattering number. Volunteering that the good number is meaningless is exactly what buys you credibility for the bad months.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Monthly social report</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One page, in the email body. Same shape every month so trends are obvious at a glance.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[BRAND] social — [month]\n\nWHAT MATTERS\nDM enquiries: [n] ([+/-n] vs last month)\nSaves (avg per post): [n] ([+/-n])\nProfile visits: [n] ([+/-n])\nLink clicks: [n] ([+/-n])\n\nCONTEXT\nPosts published: [n] of [n] planned\nReach: [n] | Followers: [n] ([+/-n])\n\nTOP 3 POSTS\n1. [post] — [n] saves, [n] DMs. Why it worked: [one real reason, not &quot;great engagement&quot;]\n2. [post] — [why]\n3. [post] — [why]\n\nWHAT FLOPPED\n[post] — [n] reach. My read: [honest reason. &quot;The hook was too clever — nobody knew what it was about in the first two seconds.&quot;]\n\nWHAT I&#x27;M CHANGING NEXT MONTH\n1. [Specific, based on the above]\n2. [Specific]\n\nWHAT I NEED FROM YOU\n[One thing.]\n\nNote on followers: [if the number is misleading, say so here before they draw the wrong conclusion.]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Use any real account you have access to, even your own, and write a full monthly report with the six sections above.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page report with a period comparison, a &#x27;didn&#x27;t work&#x27; section, and exactly three recommendations.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Reach and impressions are used correctly and not interchangeably</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a comparison period, stated</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least one metric ties to a business outcome, not just an app metric</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The &#x27;didn&#x27;t work&#x27; section is honest and specific</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Exactly three recommendations, each doable next month</span></label></li></ul></div>"},{"n":8,"title":"Capstone: four weeks of Halo-Halo House","outcome":"A complete portfolio showing a real workflow, plus the scope sheet that keeps the job survivable.","badges":["Rates","2 templates"],"minutes":120,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Show decisions, not follower counts. Nobody hiring cares that your fake brand got 12 likes. They care that you can explain why you chose a carousel over a reel.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Include the scope sheet in the portfolio, visibly. It signals to good clients that you are professional, and it quietly filters out the ones who wanted five jobs for one price.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Publish somewhere real if you can, with permission: a friend&#x27;s shop, a barangay group, a church, your own side business. A month of real posting teaches you things no simulation can.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write a 200-word case study for the front: the situation, what you did, what happened, what you would change. That is the whole thing hiring managers read.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The scope sheet that goes in the portfolio</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">INCLUDED — 2 accounts (IG, FB). 12 feed posts + 8 stories/month. 4 short videos from client footage. Community management weekdays 9am–6pm PH. Monthly report.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">APPROVALS — One approver. Assets due Thursday 5pm the week before. Two revision rounds included.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">NOT INCLUDED — Photography and videography. Paid ads and ad budget management. Influencer outreach. Customer support beyond social. TikTok. Weekend coverage. Event-day live posting.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">EXTRAS — Emergency post outside the calendar: flat fee. Extra revision round: flat fee. Additional account: monthly add-on.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">REVIEW — Scope reviewed at month 3. If actual hours exceed the agreed hours by more than 20%, we renegotiate.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The &#x27;not included&#x27; list is longer than the &#x27;included&#x27; list on purpose. That is not being difficult. That is the difference between a job that pays and a job that eats your weekends.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Pricing the Halo-Halo House scope in the real world</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">What you just built, priced as an offer. Notice how much of the price is determined by revisions and platform count, not by hours.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Content only — 12 posts/mo</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$9–13 effective</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$450–800</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You design and caption. Client posts and handles comments.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Content + scheduling — 1 platform</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$9–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$600–1,000</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The most common starter package. Easiest to deliver profitably.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Content + scheduling + community — 2 platforms</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$10–15</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$900–1,600</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Community is what makes this jump. Cap your response hours or it eats you.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Full social — 2 platforms + strategy + reporting</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$12–18</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,400–2,400</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own the numbers. Requires a 3-month minimum to show anything.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Add-ons</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">—</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$25–80 per extra reel · +40% per extra platform · $150 rush month</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Price add-ons separately from day one. This is where your margin lives.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Rule of thumb: every extra platform is +40%, not +100% — the idea is reused, the adaptation is the work. Every extra revision round beyond two is billed.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Social media scope sheet</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Attach to every proposal. The &#x27;not included&#x27; section is the most valuable part of this document.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[BRAND] — social media scope\nEffective [date]. Reviewed every 3 months.\n\nDELIVERABLES PER MONTH\n• [n] feed posts ([n] carousels, [n] statics)\n• [n] short-form videos (up to [n] seconds, from footage you supply)\n• [n] story frames\n• Captions, hashtags and scheduling for all of the above\n• Community management: comments and DMs checked [time] and [time], Mon–Fri\n• One monthly report + a 30-min review call\n\nPLATFORMS\n[Instagram] and [TikTok]. Cross-posting to [Facebook] included.\nAdding a platform: +[40]% of the monthly fee.\n\nWHAT I NEED FROM YOU\n• Raw footage and product photos by the [n]th of the prior month\n• Approvals within [n] working days of receiving the batch\n• One named person who gives final approval — not a committee\n• Access to the accounts (I&#x27;ll never ask for your password — use [Meta Business Suite / a manager invite])\n\nNOT INCLUDED (quoted separately, happily)\n• Paid ads: setup, management or spend\n• Photography or on-site filming\n• Influencer outreach and negotiation\n• Website, email marketing, print\n• Replying to comments outside my stated hours\n• Crisis comms outside working hours\n• More than 2 revision rounds per batch\n\nREVISIONS\nTwo rounds per monthly batch. Round 3+ is $[x] per post.\n&quot;Make it pop&quot; isn&#x27;t a revision — I&#x27;ll come back and ask what specifically to change.\n\nTURNAROUND\nBatch delivered by the [n]th. Approved posts scheduled within 2 working days.\nUrgent unplanned post: $[x], 24 hrs&#x27; notice minimum.\n\nPAYMENT\n$[x]/month, invoiced on the [n]th, [n]-day terms, via [method].\n3-month initial term, then rolling with 30 days&#x27; notice either side.\n\nIF WE PART WAYS\nYou keep everything — all assets, the calendar, the templates, exported and handed over within 5 working days.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Portfolio case study — the four-week story</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">How to present the capstone. Practice work, honestly labelled, told as a story with numbers.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>HALO-HALO HOUSE — four weeks of social\n(Practice scenario, not a paid client. Which means I can show you all of it.)\n\nTHE BRIEF\nA dessert shop posting twice a week with no plan: mostly product photos, captions written in a rush, no idea what worked.\n\nWHAT I BUILT\n• Four content pillars, weighted 40/25/20/15 [link]\n• A 4-week calendar: 16 posts, every one assigned a pillar and a hook [link]\n• A template set in Canva — 5 templates, brand-locked [link]\n• 16 captions with hooks written separately and tested [link]\n• Escalation rules and 12 saved replies for community management [link]\n• A QA checklist run on every post [link]\n• The scope sheet that keeps the job profitable [link]\n\nWHAT I&#x27;D WATCH\nSaves per post and DM enquiries. Not followers.\n\nTHE THINKING (this is the actual portfolio)\nThe hardest call was cutting from four platforms to two. The brief implied everything, everywhere. Two platforms done natively will beat four done by copy-paste, and I&#x27;d rather have that argument in week one than in month three.\n\n3-minute walkthrough: [Loom link]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Assemble everything from modules 1–7 into one portfolio folder with a 200-word case study on the front page and the scope sheet visible.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A shareable folder or Notion page with the brief, calendar, brand kit, templates, content, response bank, report and scope sheet.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 120 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The case study is under 200 words and says what you would change</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every asset is labelled as work for a fictional brand</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The scope sheet is in the portfolio, not hidden in a contract</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Each major decision has a one-line reason next to it</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You tested the share link in a private window</span></label></li></ul></div>"}],"quiz":[{"q":"A client asks for '12 posts a month' at a flat fee. What is the first question?","options":["What's your budget?","Am I creating the content or scheduling content you supply, and does this include comments and DMs?","Which platforms?","Do you have a Canva account?"],"answer":1,"explain":"Management, production and community management are three different jobs. Twelve posts you design from scratch plus daily DMs is maybe four times the work of scheduling twelve supplied posts."},{"q":"A customer comments publicly that they got sick after eating at the client's shop.","options":["Reply explaining the kitchen is clean and there have been no other complaints","Delete the comment and DM them privately","One short public reply, move to DM, escalate to the owner immediately, log everything","Ignore it and hope it gets buried"],"answer":2,"explain":"Health complaints are always escalated, never argued. Deleting is the worst option because screenshots survive and 'they deleted my comment' becomes the bigger story."},{"q":"Post A: 300 likes, 2 saves, 1 share. Post B: 40 likes, 30 saves, 12 shares. Which performed better?","options":["Post A, more engagement overall","Post B","They are equivalent","Depends on follower count"],"answer":1,"explain":"Saves and shares mean the content was useful enough to keep or pass on. Likes are the cheapest possible signal. B is also far more likely to keep being distributed."},{"q":"The client sends the week's photos on Friday afternoon for a Monday post, again.","options":["Work the weekend, it is only one weekend","Post without the photos","Publish what you can, tell them the Monday post moves to Wednesday, and restate the Thursday 5pm deadline in writing","Complain about it in the monthly report"],"answer":2,"explain":"Enforce the deadline calmly the first time. Late assets should move the post, not your Saturday. Absorb it once and it becomes the permanent arrangement."},{"q":"Which belongs in a monthly report for a client whose goal is catering enquiries?","options":["Follower growth and total likes","DM enquiries, link clicks, and which content drove them","Reach only","A screenshot of the best-performing post"],"answer":1,"explain":"Report against the goal that was set. Followers and likes are context at best; if catering enquiries went up, that is the headline."},{"q":"A client wants to use a trending song on a reel. What do you check?","options":["Nothing, trending sounds are fine","That it is in the platform's own commercial audio library, since business accounts have a restricted catalogue","That the song is popular enough","That the artist is not too famous"],"answer":1,"explain":"Business accounts get a smaller licensed catalogue than personal ones. Using a restricted track can get the audio muted or the post pulled, and that is your mistake to explain."}],"glossary":[{"term":"Content pillar","def":"A recurring subject category the brand posts about. Three or four, with repeatable formats."},{"term":"Content calendar","def":"The schedule of what goes out, when, on which platform, with which assets."},{"term":"Reach","def":"Unique accounts that saw the content. Not the same as impressions, and clients notice if you mix them up."},{"term":"Impressions","def":"Total times the content was displayed, including the same person seeing it repeatedly."},{"term":"Engagement rate","def":"Interactions relative to reach or followers. Always say which denominator you used."},{"term":"Saves","def":"People bookmarking a post. On Instagram this is one of the strongest quality signals there is."},{"term":"CTR","def":"Click-through rate. Clicks divided by impressions or views."},{"term":"CTA","def":"Call to action. What you want the reader to do next. One per post."},{"term":"Hook","def":"The first line or first two seconds. Where roughly 90% of your attention should go."},{"term":"UGC","def":"User-generated content. Customers' own photos and videos, used with permission."},{"term":"Carousel","def":"A multi-slide post. Usually the highest-saved format on Instagram."},{"term":"Reel / Short","def":"Short vertical video. Highest reach potential, highest production cost per minute."},{"term":"Community management","def":"Handling comments, DMs and mentions. A separate service from posting."},{"term":"Social listening","def":"Monitoring what people say about the brand, including where they did not tag it."},{"term":"Approval workflow","def":"Who reviews what, by when. Draft, in review, approved, scheduled, published."},{"term":"Boost","def":"Paying to distribute an existing post. Comes from an ad budget, not from your management fee."},{"term":"Campaign objective","def":"The outcome selected in an ad platform. Awareness, traffic, engagement, leads, sales."},{"term":"Response bank","def":"Pre-approved replies you adapt, so you are never writing from scratch under pressure."},{"term":"Scope creep","def":"Work that arrived without arriving in the contract. Handled in writing, early, or not at all."}]} as DeepCourse;

export default course;
